const r = await tools.exec_command({cmd:"node <<'NODE'
const fs = require('fs');
for (const file of ['out/audit.json', 'out/eval-manifest.json']) JSON.parse(fs.readFileSync(file, 'utf8'));
const audit = JSON.parse(fs.readFileSync('out/audit.json', 'utf8'));
const manifest = JSON.parse(fs.readFileSync('out/eval-manifest.json', 'utf8'));
const ids = new Set(manifest.cases.map(c => c.id));
const splits = manifest.cases.reduce((a,c) => { a[c.split] = (a[c.split] || 0) + 1; return a; }, {});
const missingRefs = audit.success_criteria.flatMap(s => s.covered_by_cases).filter(id => !ids.has(id));
const malformed = manifest.cases.filter(c => !c.expected_behavior?.length || !c.forbidden_behavior?.length).map(c => c.id);
const ok = manifest.cases.length >= 8 && (splits.holdout || 0) >= 2 && missingRefs.length === 0 && malformed.length === 0;
console.log(JSON.stringify({valid_json: true, cases: manifest.cases.length, splits, missing_cross_references: missingRefs, cases_missing_expectations: malformed, checks_passed: ok}, null, 2));
process.exit(ok ? 0 : 1);
